import {resolveTreatment} from './style-model.js';
import {motionSettings} from './motion.js';
import {matrix,ordered,bounds,polygon} from './model.js';
import {canvas,treat} from './treatments.js';
export class Renderer{
 constructor(){this.image=null;this.sourceId=null;this.cache=new Map();this.bytes=0;}
 async load(source){if(source?.id===this.sourceId)return;this.image?.close?.();this.image=null;this.sourceId=source?.id;this.cache.clear();this.bytes=0;if(source)this.image=await createImageBitmap(await(await fetch(source.data)).blob());}
 texture(f,quality,motion={},params=f.params){const box=bounds(f.source.polygon),key=JSON.stringify([this.sourceId,f.source,f.type,params,quality,motion]);if(this.cache.has(key)){const hit=this.cache.get(key);this.cache.delete(key);this.cache.set(key,hit);return {image:hit,box}}const result=treat(this.image,box,f.type,params,quality,motion);this.cache.set(key,result);this.bytes+=result.width*result.height*4;while(this.bytes>64*1024*1024&&this.cache.size>1){const key=this.cache.keys().next().value,old=this.cache.get(key);this.bytes-=old.width*old.height*4;this.cache.delete(key)}return {image:result,box};}
 draw(ctx,s,camera,width,height,quality=1){ctx.clearRect(0,0,width,height);if(!this.image)return;ctx.save();ctx.setTransform(camera.scale,0,0,camera.scale,camera.x,camera.y);const fs=ordered(s),identity=f=>{const t=f.transform,j=f.jitter;return !t.x&&!t.y&&!t.angle&&t.sx===1&&t.sy===1&&t.opacity===1&&!j.x&&!j.y&&!j.angle&&j.scale===1};if(fs.length===s.fragments.length&&fs.every(f=>{const p=resolveTreatment(s,f);return f.type==='original'&&identity(f)&&p.brightness===0&&p.contrast===1;})){ctx.drawImage(this.image,0,0,s.source.width,s.source.height);ctx.restore();return;}
 for(const f of fs){const b=bounds(polygon(f));if(b.right*camera.scale+camera.x<0||b.x*camera.scale+camera.x>width||b.bottom*camera.scale+camera.y<0||b.y*camera.scale+camera.y>height)continue;ctx.save();ctx.transform(...matrix(f));ctx.globalAlpha=f.transform.opacity;ctx.beginPath();f.source.polygon.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.closePath();ctx.clip();const params=resolveTreatment(s,f);if(f.type==='original'&&params.brightness===0&&params.contrast===1)ctx.drawImage(this.image,0,0,s.source.width,s.source.height);else{const settings=motionSettings(s,f),animate=settings.enabled&&['ascii','halftone','contour'].includes(f.type),frame=Math.floor((s.motionTime||0)*settings.fps/1000)%(settings.fps*4),motion=animate?{frame,time:frame/settings.fps,fps:settings.fps,amount:settings.amount,speed:settings.speed,seed:settings.seed}:{};const {image,box}=this.texture(f,quality,motion,params);ctx.drawImage(image,box.x,box.y,box.right-box.x,box.bottom-box.y)}ctx.restore();}ctx.restore();}
 render(s,w,h,camera,quality=1){const output=canvas(w,h);this.draw(output.getContext('2d'),s,camera,w,h,quality);return output;}
}
